 10	import javax.sql.DataSource;
 11	import java.sql.Connection;
 12	import java.sql.SQLException;
 13	
 14	public class App {
 15	    private static final Logger logger = LoggerFactory.getLogger(App.class);
 16	
 17	    public static void main(String[] args) {
 18	        DataSource ds = createDataSource();
 19	        runMigrations(ds);
 20	
 21	        Javalin app = Javalin.create();
 22	
 23	        com.posadamarealta.handlers.RoomHandler roomHandler = new com.posadamarealta.handlers.RoomHandler(ds);
 24	        com.posadamarealta.handlers.ReservationHandler reservationHandler = new com.posadamarealta.handlers.ReservationHandler(ds);
 25	        com.posadamarealta.handlers.MessageHandler messageHandler = new com.posadamarealta.handlers.MessageHandler(ds);
 26	        com.posadamarealta.handlers.ReportHandler reportHandler = new com.posadamarealta.handlers.ReportHandler(ds);
 27	
 28	        app.get("/rooms", roomHandler::list);
 29	        app.post("/reservations", reservationHandler::create);
 30	        app.get("/reservations/{id}", reservationHandler::get);
 31	        app.post("/reservations/{id}/confirmation", reservationHandler::confirm);
 32	        app.post("/reservations/{id}/cancellation", reservationHandler::cancel);
 33	        app.post("/reservations/{id}/check-in", reservationHandler::checkIn);
 34	        app.post("/reservations/{id}/check-out", reservationHandler::checkOut);
 35	        app.get("/reservations/{id}/document", reservationHandler::getDocument);
 36	        app.get("/messages", messageHandler::list);
 37	        app.get("/reports/occupancy", reportHandler::occupancy);
 38	        app.get("/reports/revenue", reportHandler::revenue);
 39	
 40	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 41	        app.start(port);
 42	        logger.info("Server started on port {}", port);
 43	    }
 44	
 45	    private static DataSource createDataSource() {
 46	        String dbUrl = System.getenv("DB_URL");
 47	        String dbUser = System.getenv("DB_USER");
 48	        String dbPassword = System.getenv("DB_PASSWORD");
 49	
 50	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 51	            throw new IllegalArgumentException("Missing database environment variables");
 52	        }
 53	
 54	        HikariConfig config = new HikariConfig();
 55	        config.setJdbcUrl(dbUrl);
 56	        config.setUsername(dbUser);
 57	        config.setPassword(dbPassword);
 58	        config.setMaximumPoolSize(10);
 59	        config.setMinimumIdle(2);
 60	
 61	        return new HikariDataSource(config);
 62	    }
 63	
 64	    private static void runMigrations(DataSource ds) {
 65	        try (Connection conn = ds.getConnection()) {
 66	            conn.createStatement().execute("""
 67	                CREATE TABLE IF NOT EXISTS rooms (
 68	                    number INTEGER PRIMARY KEY,
 69	                    type VARCHAR(20) NOT NULL,
 70	                    capacity INTEGER NOT NULL,
 71	                    nightly_rate NUMERIC(10,2) NOT NULL
 72	                )
 73	                """);
 74	
 75	            conn.createStatement().execute("""
 76	                CREATE TABLE IF NOT EXISTS reservations (
 77	                    id SERIAL PRIMARY KEY,
 78	                    room_number INTEGER NOT NULL REFERENCES rooms(number),
 79	                    guest_name VARCHAR(255) NOT NULL,
 80	                    guest_email VARCHAR(255) NOT NULL,
 81	                    guest_cpf VARCHAR(20),
 82	                    company_cnpj VARCHAR(30),
 83	                    company_name VARCHAR(255),
 84	                    guest_passport VARCHAR(50),
 85	                    guest_country VARCHAR(100),
 86	                    check_in DATE NOT NULL,
 87	                    check_out DATE NOT NULL,
 88	                    guests INTEGER NOT NULL,
 89	                    rate_plan VARCHAR(50) NOT NULL,
 90	                    nights INTEGER NOT NULL,
 91	                    subtotal NUMERIC(10,2) NOT NULL,
 92	                    discount NUMERIC(10,2) NOT NULL,
 93	                    total NUMERIC(10,2) NOT NULL,
 94	                    status VARCHAR(50) NOT NULL,
 95	                    amount_paid NUMERIC(10,2) NOT NULL DEFAULT 0,
 96	                    refund NUMERIC(10,2),
 97	                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
 98	                )
 99	                """);
100	
101	            conn.createStatement().execute("""
102	                CREATE TABLE IF NOT EXISTS messages (
103	                    id SERIAL PRIMARY KEY,
104	                    channel VARCHAR(50) NOT NULL,
105	                    "to" VARCHAR(255) NOT NULL,
106	                    subject VARCHAR(255),
107	                    body TEXT NOT NULL,
108	                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
109	                )
110	                """);
111	
112	            conn.createStatement().execute("""
113	                INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
114	                (101, 'STANDARD', 2, 249.90),
115	                (102, 'STANDARD', 2, 249.90),
116	                (201, 'DELUXE', 3, 389.90),
117	                (202, 'DELUXE', 3, 389.90),
118	                (301, 'SUITE', 4, 579.90)
119	                ON CONFLICT (number) DO NOTHING
120	                """);
121	
122	            logger.info("Migrations completed");
123	        } catch (SQLException e) {
124	            throw new RuntimeException("Migration failed", e);
125	        }
126	    }
127	}
