145	package com.posadamarealta.handlers;
146	
147	import com.posadamarealta.model.Reservation;
148	import com.posadamarealta.repository.ReservationRepository;
149	import com.posadamarealta.repository.RoomRepository;
150	import com.posadamarealta.service.UtilService;
151	import io.javalin.http.Context;
152	import javax.sql.DataSource;
153	import java.math.BigDecimal;
154	import java.time.LocalDate;
155	import java.time.YearMonth;
156	import java.util.ArrayList;
157	import java.util.List;
158	import java.util.stream.Collectors;
159	
160	public class ReportHandler {
161	    private final ReservationRepository reservationRepo;
162	    private final RoomRepository roomRepo;
163	
164	    public ReportHandler(DataSource ds) {
165	        this.reservationRepo = new ReservationRepository(ds);
166	        this.roomRepo = new RoomRepository(ds);
167	    }
168	
169	    public void occupancy(Context ctx) {
170	        try {
171	            String dateStr = ctx.queryParam("date");
172	            if (dateStr == null) {
173	                ctx.status(400).json(new java.util.HashMap<String, String>() {{
174	                    put("error", "INVALID_REQUEST");
175	                    put("message", "Missing date parameter");
176	                }});
177	                return;
178	            }
179	
180	            LocalDate date = UtilService.parseDate(dateStr);
181	
182	            StringBuilder csv = new StringBuilder();
183	            csv.append("room,type,reservation,check_in,check_out\n");
184	
185	            List<String> rows = new ArrayList<>();
186	            int occupiedCount = 0;
187	
188	            for (var room : roomRepo.findAll()) {
189	                List<Reservation> reservations = reservationRepo.findByRoomAndDate(room.number, date);
190	                if (!reservations.isEmpty()) {
191	                    Reservation res = reservations.get(0);
192	                    rows.add(room.number + "," + room.type + "," + res.id + "," +
193	                            UtilService.formatDateISO(res.checkIn) + "," +
194	                            UtilService.formatDateISO(res.checkOut));
195	                    occupiedCount++;
196	                }
197	            }
198	
199	            rows.forEach(row -> csv.append(row).append("\n"));
200	            csv.append("total,").append(occupiedCount).append("/5\n");
201	
202	            ctx.contentType("text/csv;charset=utf-8");
203	            ctx.result(csv.toString());
204	        } catch (Exception e) {
205	            ctx.status(400).json(new java.util.HashMap<String, String>() {{
206	                put("error", "INVALID_REQUEST");
207	                put("message", "Invalid date format");
208	            }});
209	        }
210	    }
211	
212	    public void revenue(Context ctx) {
213	        try {
214	            String monthStr = ctx.queryParam("month");
215	            if (monthStr == null) {
216	                ctx.status(400).json(new java.util.HashMap<String, String>() {{
217	                    put("error", "INVALID_REQUEST");
218	                    put("message", "Missing month parameter");
219	                }});
220	                return;
221	            }
222	
223	            YearMonth yearMonth = UtilService.parseYearMonth(monthStr);
224	            List<Reservation> reservations = reservationRepo.findByMonthAndStarting(yearMonth);
225	
226	            StringBuilder csv = new StringBuilder();
227	            csv.append("reservation,room,check_in,check_out,status,amount\n");
228	
229	            BigDecimal total = BigDecimal.ZERO;
230	            for (Reservation res : reservations) {
231	                BigDecimal amount = res.amountPaid;
232	                if (res.refund != null) {
233	                    amount = amount.subtract(res.refund);
234	                }
235	
236	                if (amount.compareTo(BigDecimal.ZERO) > 0) {
237	                    csv.append(res.id).append(",")
238	                       .append(res.roomNumber).append(",")
239	                       .append(UtilService.formatDateISO(res.checkIn)).append(",")
240	                       .append(UtilService.formatDateISO(res.checkOut)).append(",")
241	                       .append(res.status).append(",")
242	                       .append(UtilService.formatCSVMoney(amount)).append("\n");
243	                    total = total.add(amount);
244	                }
245	            }
246	
247	            csv.append("total,,,,").append(UtilService.formatCSVMoney(total)).append("\n");
248	
249	            ctx.contentType("text/csv;charset=utf-8");
250	            ctx.result(csv.toString());
251	        } catch (Exception e) {
252	            ctx.status(400).json(new java.util.HashMap<String, String>() {{
253	                put("error", "INVALID_REQUEST");
254	                put("message", "Invalid month format");
255	            }});
256	        }
257	    }
258	}
259	package com.posadamarealta.handlers;
260	
261	import com.fasterxml.jackson.databind.JsonNode;
262	import com.fasterxml.jackson.databind.ObjectMapper;
263	import com.posadamarealta.model.Document;
264	import com.posadamarealta.model.Reservation;
265	import com.posadamarealta.model.Room;
266	import com.posadamarealta.repository.MessageRepository;
267	import com.posadamarealta.repository.ReservationRepository;
268	import com.posadamarealta.repository.RoomRepository;
269	import com.posadamarealta.service.DocumentService;
270	import com.posadamarealta.service.ReservationService;
271	import com.posadamarealta.service.UtilService;
272	import io.javalin.http.Context;
273	import javax.sql.DataSource;
274	import java.time.LocalDate;
275	
276	public class ReservationHandler {
277	    private final ReservationService reservationService;
278	    private final RoomRepository roomRepo;
279	    private final ReservationRepository reservationRepo;
280	    private final MessageRepository messageRepo;
281	    private final ObjectMapper mapper = new ObjectMapper();
282	
283	    public ReservationHandler(DataSource ds) {
284	        this.reservationRepo = new ReservationRepository(ds);
285	        this.roomRepo = new RoomRepository(ds);
286	        this.messageRepo = new MessageRepository(ds);
287	        this.reservationService = new ReservationService(reservationRepo, roomRepo, messageRepo);
288	    }
289	
290	    public void create(Context ctx) {
291	        try {
292	            JsonNode body = mapper.readTree(ctx.body());
293	
294	            if (!body.has("roomNumber") || !body.has("guestName") || !body.has("guestEmail") ||
295	                !body.has("checkIn") || !body.has("checkOut") || !body.has("guests") || !body.has("ratePlan")) {
296	                sendError(ctx, 400, "INVALID_REQUEST", "Missing required fields");
297	                return;
298	            }
299	
300	            int roomNumber = body.get("roomNumber").asInt();
301	            String guestName = body.get("guestName").asText();
302	            String guestEmail = body.get("guestEmail").asText();
303	            String guestCpf = body.has("guestCpf") ? body.get("guestCpf").asText() : null;
304	            String companyCnpj = body.has("companyCnpj") ? body.get("companyCnpj").asText() : null;
305	            String companyName = body.has("companyName") ? body.get("companyName").asText() : null;
306	            String guestPassport = body.has("guestPassport") ? body.get("guestPassport").asText() : null;
307	            String guestCountry = body.has("guestCountry") ? body.get("guestCountry").asText() : null;
308	            String checkInStr = body.get("checkIn").asText();
309	            String checkOutStr = body.get("checkOut").asText();
310	            int guests = body.get("guests").asInt();
311	            String ratePlan = body.get("ratePlan").asText();
312	
313	            LocalDate checkIn = UtilService.parseDate(checkInStr);
314	            LocalDate checkOut = UtilService.parseDate(checkOutStr);
315	
316	            Reservation reservation = reservationService.createReservation(roomNumber, guestName, guestEmail,
317	                guestCpf, companyCnpj, companyName, guestPassport, guestCountry,
318	                checkIn, checkOut, guests, ratePlan);
319	
320	            ctx.status(201);
321	            ctx.json(reservation);
322	        } catch (IllegalArgumentException e) {
323	            String errorCode = e.getMessage();
324	            if ("ROOM_NOT_FOUND".equals(errorCode)) {
325	                sendError(ctx, 404, "ROOM_NOT_FOUND", "Room not found");
326	            } else if ("ROOM_UNAVAILABLE".equals(errorCode)) {
327	                sendError(ctx, 409, "ROOM_UNAVAILABLE", "Room is not available for the requested dates");
328	            } else if ("CAPACITY_EXCEEDED".equals(errorCode)) {
329	                sendError(ctx, 422, "CAPACITY_EXCEEDED", "Number of guests exceeds room capacity");
330	            } else {
331	                sendError(ctx, 400, "INVALID_REQUEST", "Invalid request");
332	            }
333	        } catch (Exception e) {
334	            sendError(ctx, 400, "INVALID_REQUEST", "Invalid request");
335	        }
336	    }
337	
338	    public void get(Context ctx) {
339	        try {
340	            int id = Integer.parseInt(ctx.pathParam("id"));
341	            Reservation reservation = reservationService.getReservation(id);
342	            ctx.json(reservation);
343	        } catch (IllegalArgumentException e) {
344	            sendError(ctx, 404, "RESERVATION_NOT_FOUND", "Reservation not found");
345	        } catch (Exception e) {
346	            sendError(ctx, 400, "INVALID_REQUEST", "Invalid request");
347	        }
348	    }
349	
350	    public void confirm(Context ctx) {
351	        try {
352	            int id = Integer.parseInt(ctx.pathParam("id"));
353	            Reservation reservation = reservationService.confirmReservation(id);
354	            ctx.json(reservation);
355	        } catch (IllegalArgumentException e) {
356	            String errorCode = e.getMessage();
357	            if ("RESERVATION_NOT_FOUND".equals(errorCode)) {
358	                sendError(ctx, 404, "RESERVATION_NOT_FOUND", "Reservation not found");
359	            } else if ("OPERATION_NOT_ALLOWED".equals(errorCode)) {
360	                sendError(ctx, 409, "OPERATION_NOT_ALLOWED", "Cannot confirm a reservation in this status");
361	            } else {
362	                sendError(ctx, 400, "INVALID_REQUEST", "Invalid request");
363	            }
364	        }
365	    }
366	
367	    public void cancel(Context ctx) {
368	        try {
369	            int id = Integer.parseInt(ctx.pathParam("id"));
370	            Reservation reservation = reservationService.cancelReservation(id);
371	            ctx.json(reservation);
372	        } catch (IllegalArgumentException e) {
373	            String errorCode = e.getMessage();
374	            if ("RESERVATION_NOT_FOUND".equals(errorCode)) {
375	                sendError(ctx, 404, "RESERVATION_NOT_FOUND", "Reservation not found");
376	            } else if ("OPERATION_NOT_ALLOWED".equals(errorCode)) {
377	                sendError(ctx, 409, "OPERATION_NOT_ALLOWED", "Cannot cancel a reservation in this status");
378	            } else {
379	                sendError(ctx, 400, "INVALID_REQUEST", "Invalid request");
380	            }
381	        }
382	    }
383	
384	    public void checkIn(Context ctx) {
385	        try {
386	            int id = Integer.parseInt(ctx.pathParam("id"));
387	            Reservation reservation = reservationService.checkIn(id);
388	            ctx.json(reservation);
389	        } catch (IllegalArgumentException e) {
390	            String errorCode = e.getMessage();
391	            if ("RESERVATION_NOT_FOUND".equals(errorCode)) {
392	                sendError(ctx, 404, "RESERVATION_NOT_FOUND", "Reservation not found");
393	            } else if ("OPERATION_NOT_ALLOWED".equals(errorCode)) {
394	                sendError(ctx, 409, "OPERATION_NOT_ALLOWED", "Cannot check in a reservation in this status");
395	            } else {
396	                sendError(ctx, 400, "INVALID_REQUEST", "Invalid request");
397	            }
398	        }
399	    }
400	
401	    public void checkOut(Context ctx) {
402	        try {
403	            int id = Integer.parseInt(ctx.pathParam("id"));
404	            Reservation reservation = reservationService.checkOut(id);
405	            Room room = roomRepo.findByNumber(reservation.roomNumber)
406	                .orElseThrow(() -> new IllegalArgumentException("ROOM_NOT_FOUND"));
407	            Document document = DocumentService.generate(reservation, room.type);
408	            ctx.json(document);
409	        } catch (IllegalArgumentException e) {
410	            String errorCode = e.getMessage();
411	            if ("RESERVATION_NOT_FOUND".equals(errorCode)) {
412	                sendError(ctx, 404, "RESERVATION_NOT_FOUND", "Reservation not found");
413	            } else if ("OPERATION_NOT_ALLOWED".equals(errorCode)) {
414	                sendError(ctx, 409, "OPERATION_NOT_ALLOWED", "Cannot check out a reservation in this status");
415	            } else {
416	                sendError(ctx, 400, "INVALID_REQUEST", "Invalid request");
417	            }
418	        }
419	    }
420	
421	    public void getDocument(Context ctx) {
422	        try {
423	            int id = Integer.parseInt(ctx.pathParam("id"));
424	            Reservation reservation = reservationService.getReservation(id);
425	
426	            if (!("CONFIRMED".equals(reservation.status) || "CHECKED_IN".equals(reservation.status) || "CHECKED_OUT".equals(reservation.status))) {
427	                sendError(ctx, 409, "OPERATION_NOT_ALLOWED", "Document is only available for paid reservations");
428	                return;
429	            }
430	
431	            Room room = roomRepo.findByNumber(reservation.roomNumber)
432	                .orElseThrow(() -> new IllegalArgumentException("ROOM_NOT_FOUND"));
433	            Document document = DocumentService.generate(reservation, room.type);
434	            ctx.json(document);
435	        } catch (IllegalArgumentException e) {
436	            String errorCode = e.getMessage();
437	            if ("RESERVATION_NOT_FOUND".equals(errorCode)) {
438	                sendError(ctx, 404, "RESERVATION_NOT_FOUND", "Reservation not found");
439	            } else {
440	                sendError(ctx, 400, "INVALID_REQUEST", "Invalid request");
441	            }
442	        }
443	    }
444	
445	    private void sendError(Context ctx, int status, String code, String message) {
446	        ctx.status(status);
447	        ctx.json(new java.util.HashMap<String, String>() {{
448	            put("error", code);
449	            put("message", message);
450	        }});
451	    }
452	}
