300	            int roomNumber = body.get("roomNumber").asInt();
301	            String guestName = body.get("guestName").asText();
302	            String guestEmail = body.get("guestEmail").asText();
303	            String guestCpf = body.has("guestCpf") ? body.get("guestCpf").asText() : null;
304	            String companyCnpj = body.has("companyCnpj") ? body.get("companyCnpj").asText() : null;
305	            String companyName = body.has("companyName") ? body.get("companyName").asText() : null;
