    10	    public static Document generate(Reservation reservation, String roomType) {
    11	        Document doc = new Document();
    12	        doc.reservationId = reservation.id;
    13	        doc.roomNumber = reservation.roomNumber;
    14	        doc.roomType = roomType;
    15	        doc.guestName = reservation.guestName;
    16	        doc.guestCpf = reservation.guestCpf;
    17	        doc.companyCnpj = reservation.companyCnpj;
    18	        doc.companyName = reservation.companyName;
    19	        doc.guestPassport = reservation.guestPassport;
    20	        doc.guestCountry = reservation.guestCountry;
    21	        doc.checkIn = reservation.checkIn;
    22	        doc.checkOut = reservation.checkOut;
    23	        doc.nights = reservation.nights;
    24	        doc.subtotal = reservation.subtotal;
    25	        doc.discount = reservation.discount;
    26	        doc.total = reservation.total;
    27	
    28	        if (reservation.guestCpf != null) {
    29	            doc.title = "Comprovante de reserva";
    30	            doc.text = generateReceipt(doc);
    31	        } else if (reservation.companyCnpj != null) {
    32	            doc.title = "Fatura de hospedagem";
    33	            doc.text = generateInvoice(doc);
    34	        } else if (reservation.guestPassport != null) {
    35	            doc.title = "Booking receipt";
    36	            doc.text = generateBookingReceipt(doc);
    37	        }
    38	
    39	        return doc;
    40	    }
    41	
    42	    private static String generateReceipt(Document doc) {
    43	        StringBuilder sb = new StringBuilder();
    44	        sb.append("Comprovante de reserva nº ").append(doc.reservationId).append("\n");
    45	        sb.append("Hóspede: ").append(doc.guestName).append(" (CPF ").append(formatCPF(doc.guestCpf)).append(")\n");
    46	        sb.append("Quarto: ").append(doc.roomNumber).append(" (").append(doc.roomType).append(")\n");
    47	        sb.append("Entrada: ").append(UtilService.formatDate(doc.checkIn));
    48	        sb.append(" | Saída: ").append(UtilService.formatDate(doc.checkOut));
    49	        sb.append(" | ").append(doc.nights).append(doc.nights == 1 ? " diária" : " diárias").append("\n");
    50	        sb.append("Diárias: ").append(UtilService.formatMoney(doc.subtotal)).append("\n");
    51	
    52	        if (doc.discount.compareTo(BigDecimal.ZERO) > 0) {
    53	            sb.append("Desconto: ").append(UtilService.formatMoney(doc.discount)).append("\n");
    54	        }
    55	
    56	        sb.append("Total: ").append(UtilService.formatMoney(doc.total));
    57	        return sb.toString();
    58	    }
    59	
    60	    private static String generateInvoice(Document doc) {
    61	        StringBuilder sb = new StringBuilder();
    62	        BigDecimal iss = UtilService.roundHalfEven(doc.total.multiply(new BigDecimal("0.05")));
    63	
    64	        sb.append("Fatura de hospedagem nº ").append(doc.reservationId).append("\n");
    65	        sb.append("Empresa: ").append(doc.companyName).append(" (CNPJ ").append(formatCNPJ(doc.companyCnpj)).append(")\n");
    66	        sb.append("Hóspede: ").append(doc.guestName).append("\n");
    67	        sb.append("Quarto: ").append(doc.roomNumber).append(" (").append(doc.roomType).append(")\n");
    68	        sb.append("Entrada: ").append(UtilService.formatDate(doc.checkIn));
    69	        sb.append(" | Saída: ").append(UtilService.formatDate(doc.checkOut));
    70	        sb.append(" | ").append(doc.nights).append(doc.nights == 1 ? " diária" : " diárias").append("\n");
    71	        sb.append("Diárias: ").append(UtilService.formatMoney(doc.subtotal)).append("\n");
    72	
    73	        if (doc.discount.compareTo(BigDecimal.ZERO) > 0) {
    74	            sb.append("Desconto: ").append(UtilService.formatMoney(doc.discount)).append("\n");
    75	        }
    76	
    77	        sb.append("Total: ").append(UtilService.formatMoney(doc.total)).append("\n");
    78	        sb.append("ISS retido (5%): ").append(UtilService.formatMoney(iss));
    79	        return sb.toString();
    80	    }
    81	
    82	    private static String generateBookingReceipt(Document doc) {
    83	        StringBuilder sb = new StringBuilder();
    84	        sb.append("Booking receipt no. ").append(doc.reservationId).append("\n");
    85	        sb.append("Guest: ").append(doc.guestName);
    86	        sb.append(" (passport ").append(doc.guestPassport).append(", ").append(doc.guestCountry).append(")\n");
    87	        sb.append("Room: ").append(doc.roomNumber).append(" (").append(doc.roomType).append(")\n");
    88	        sb.append("Check-in: ").append(UtilService.formatDateEnglish(doc.checkIn));
    89	        sb.append(" | Check-out: ").append(UtilService.formatDateEnglish(doc.checkOut));
    90	        sb.append(" | ").append(doc.nights).append(doc.nights == 1 ? " night" : " nights").append("\n");
    91	        sb.append("Nights: ").append(UtilService.formatMoneyEnglish(doc.subtotal)).append("\n");
    92	
    93	        if (doc.discount.compareTo(BigDecimal.ZERO) > 0) {
    94	            sb.append("Discount: ").append(UtilService.formatMoneyEnglish(doc.discount)).append("\n");
    95	        }
    96	
    97	        sb.append("Total: ").append(UtilService.formatMoneyEnglish(doc.total));
    98	        return sb.toString();
    99	    }
   100	
   101	    private static String formatCPF(String cpf) {
   102	        if (cpf == null || cpf.length() != 11) return cpf;
   103	        return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
   104	               cpf.substring(6, 9) + "-" + cpf.substring(9);
   105	    }
   106	
   107	    private static String formatCNPJ(String cnpj) {
   108	        if (cnpj == null || cnpj.length() != 14) return cnpj;
   109	        return cnpj.substring(0, 2) + "." + cnpj.substring(2, 5) + "." +
   110	               cnpj.substring(5, 8) + "/" + cnpj.substring(8, 12) + "-" + cnpj.substring(12);
   111	    }
