    24	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail,
    25	                                        String guestCpf, String companyCnpj, String companyName,
    26	                                        String guestPassport, String guestCountry,
    27	                                        LocalDate checkIn, LocalDate checkOut, int guests,
    28	                                        String ratePlan) {
    29	        // Validate room exists
    30	        Room room = roomRepo.findByNumber(roomNumber)
    31	            .orElseThrow(() -> new IllegalArgumentException("ROOM_NOT_FOUND"));
    32	
    33	        // Validate dates
    34	        if (checkIn.isAfter(checkOut) || checkIn.equals(checkOut)) {
    35	            throw new IllegalArgumentException("INVALID_REQUEST");
    36	        }
    37	
    38	        int nights = UtilService.calculateNights(checkIn, checkOut);
    39	        if (nights < 1) {
    40	            throw new IllegalArgumentException("INVALID_REQUEST");
    41	        }
    42	
    43	        // Validate guests
    44	        if (guests < 1 || guests > room.capacity) {
    45	            throw new IllegalArgumentException(guests > room.capacity ? "CAPACITY_EXCEEDED" : "INVALID_REQUEST");
    46	        }
    47	
    48	        // Validate identification
    49	        int idCount = (guestCpf != null ? 1 : 0) + (companyCnpj != null ? 1 : 0) + (guestPassport != null ? 1 : 0);
    50	        if (idCount != 1) {
    51	            throw new IllegalArgumentException("INVALID_REQUEST");
    52	        }
    53	
    54	        // Check if company fields are provided when using CNPJ
    55	        if (companyCnpj != null && companyName == null) {
    56	            throw new IllegalArgumentException("INVALID_REQUEST");
    57	        }
    58	
    59	        // Check if country field is provided when using passport
    60	        if (guestPassport != null && guestCountry == null) {
    61	            throw new IllegalArgumentException("INVALID_REQUEST");
    62	        }
    63	
    64	        // Check room availability
    65	        LocalDate current = checkIn;
