   104	        reservationRepo.confirm(reservationId, reservation.total);
   105	
   106	        Reservation updated = reservationRepo.findById(reservationId)
   107	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
   108	
   109	        Room room = roomRepo.findByNumber(reservation.roomNumber)
   110	            .orElseThrow(() -> new IllegalArgumentException("ROOM_NOT_FOUND"));
   111	
   112	        String documentText = DocumentService.generate(updated, room.type).text;
   113	
   114	        String subject = "Reserva confirmada - Pousada Maré Alta";
   115	        String body = "Olá, " + reservation.guestName + "!\n\n" +
   116	            "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
   117	            documentText + "\n\n" +
   118	            "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
   119	            "Até breve!";
   120	
   121	        messageRepo.save("EMAIL", reservation.guestEmail, subject, body);
   122	
   123	        return updated;
