   126	    public Reservation cancelReservation(int reservationId) {
   127	        Reservation reservation = reservationRepo.findById(reservationId)
   128	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
   129	
   130	        if (!("PENDING".equals(reservation.status) || "CONFIRMED".equals(reservation.status))) {
   131	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
