    14	    public static boolean isHighSeason(LocalDate date) {
    15	        int month = date.getMonthValue();
    16	        int day = date.getDayOfMonth();
    17	
    18	        return (month == 7) || (month == 12) || (month == 1) || (month == 2);
    19	    }
