    21	    public static BigDecimal roundHalfEven(BigDecimal value) {
    22	        return value.setScale(2, RoundingMode.HALF_EVEN);
    23	    }
    24	
    25	    public static BigDecimal calculateNightlyRate(BigDecimal baseRate, LocalDate date) {
    26	        if (isHighSeason(date)) {
    27	            return roundHalfEven(baseRate.multiply(new BigDecimal("1.20")));
    28	        }
    29	        return baseRate;
    30	    }
