    48	    public static String formatMoney(BigDecimal value) {
    49	        String parts[] = String.format("%.2f", value).split("\\.");
    50	        String integer = parts[0];
    51	        String decimal = parts[1];
    52	
    53	        StringBuilder sb = new StringBuilder("R$ ");
    54	        int len = integer.length();
    55	        for (int i = 0; i < len; i++) {
    56	            if (i > 0 && (len - i) % 3 == 0) {
    57	                sb.append(".");
    58	            }
    59	            sb.append(integer.charAt(i));
    60	        }
    61	        sb.append(",").append(decimal);
    62	        return sb.toString();
    63	    }
