    66	        String parts[] = String.format("%.2f", value).split("\\.");
    67	        String integer = parts[0];
    68	        String decimal = parts[1];
    69	
    70	        StringBuilder sb = new StringBuilder("BRL ");
    71	        int len = integer.length();
    72	        for (int i = 0; i < len; i++) {
    73	            if (i > 0 && (len - i) % 3 == 0) {
    74	                sb.append(",");
    75	            }
    76	            sb.append(integer.charAt(i));
    77	        }
    78	        sb.append(".").append(decimal);
