    32	                "company_cnpj, company_name, guest_passport, guest_country, check_in, check_out, " +
    33	                "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid) " +
    34	                "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
    35	                Statement.RETURN_GENERATED_KEYS)) {
    36	
    37	            stmt.setInt(1, roomNumber);
    38	            stmt.setString(2, guestName);
    39	            stmt.setString(3, guestEmail);
    40	            stmt.setString(4, guestCpf);
