    51	            stmt.setBigDecimal(15, discount);
    52	            stmt.setBigDecimal(16, total);
    53	            stmt.setString(17, "PENDING");
    54	            stmt.setBigDecimal(18, BigDecimal.ZERO);
    55	
    56	            stmt.executeUpdate();
    57	
    58	            try (var keys = stmt.getGeneratedKeys()) {
    59	                if (keys.next()) {
    60	                    int id = keys.getInt(1);
    61	                    return new Reservation(id, roomNumber, guestName, guestEmail, guestCpf,
    62	                        companyCnpj, companyName, guestPassport, guestCountry,
    63	                        checkIn, checkOut, guests, ratePlan, nights, subtotal, discount, total,
    64	                        "PENDING", BigDecimal.ZERO, null);
    65	                }
    66	            }
    67	        } catch (SQLException e) {
    68	            throw new RuntimeException(e);
    69	        }
    70	        throw new RuntimeException("Failed to create reservation");
